package com.example.dsatracker.controller;import com.example.dsatracker.dto.SubmissionRequestDTO;import com.example.dsatracker.dto.SubmissionResponseDTO;import com.example.dsatracker.service.SubmissionService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/submissions")public class SubmissionController {    private final SubmissionService service;    public SubmissionController(SubmissionService service) {        this.service = service;    }    @PostMapping    public ResponseEntity<SubmissionResponseDTO> createSubmission(            @Valid @RequestBody SubmissionRequestDTO request) {        SubmissionResponseDTO response =                service.createSubmission(request);        return ResponseEntity                .status(HttpStatus.CREATED)                .body(response);    }}